#include "crimsonland_resource.h"

static __forceinline char *decode_destination_data_bytes_remaining(
    void *pcm_data,
    unsigned int pcm_bytes,
    unsigned int remaining)
{
    return (char *)((unsigned int)pcm_data + pcm_bytes - remaining);
}

static __forceinline char *decode_destination_bytes_data_remaining(
    unsigned int pcm_bytes,
    void *pcm_data,
    unsigned int remaining)
{
    return (char *)(pcm_bytes - remaining + (unsigned int)pcm_data);
}

static __forceinline char *decode_destination_remaining_data_bytes(
    unsigned int remaining,
    void *pcm_data,
    unsigned int pcm_bytes)
{
    return (char *)(pcm_bytes - remaining + (unsigned int)pcm_data);
}
